    dorso(); inclina(z); cuentaBind(z);
    nom.oninput = () => { S.name = nom.value.trim(); save(); };
    nom.onchange = () => { S.name = nom.value = nom.value.trim(); save(); if (pfCarne().pose === 'letra') $('.cn-foto', z).innerHTML = pfCara(pfCarne()); };
